// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, CopyIcon, RefreshCwIcon, SearchIcon } from 'lucide-react'

import { BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import { CAPTIONS, LOCAL, MATCHES, QUERY, SESSION, STEP_AFTER, preview, type Entry } from './script'

const PANEL = 252
const keyId = (key: string) => key.replace(/[^a-z0-9]+/gi, '-').toLowerCase()
const HIDDEN = LOCAL.filter((entry) => !MATCHES.includes(entry))
const COPIED = MATCHES[0]

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const collapse = (entries: Entry[], hide: boolean) => {
    const rows = entries.map(([key]) => q(`row-local-${keyId(key)}`))
    tl.to(
      rows,
      hide
        ? {
            height: 0,
            marginBottom: 0,
            opacity: 0,
            borderWidth: 0,
            paddingTop: 0,
            paddingBottom: 0,
            duration: 0.3,
          }
        : {
            height: 'auto',
            marginBottom: 4,
            opacity: 1,
            borderWidth: 1,
            paddingTop: 5,
            paddingBottom: 5,
            duration: 0.3,
          },
      '<',
    )
  }
  const tab = (which: 'local' | 'session') => {
    const on = { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)', duration: 0.15 }
    const off = { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)', duration: 0.15 }
    tl.to(q('tab-local'), which === 'local' ? on : off, '<')
    tl.to(q('tab-session'), which === 'session' ? on : off, '<')
    tl.to(q('list-local'), { opacity: which === 'local' ? 1 : 0, duration: 0.15 }, '<')
    tl.to(q('list-session'), { opacity: which === 'session' ? 1 : 0, duration: 0.2 }, '<')
  }

  step(0)
  tl.to(q('loading'), { opacity: 0, duration: 0.2 }, 0.5)
  tl.fromTo(q('tabs'), { opacity: 0 }, { opacity: 1, duration: 0.2, immediateRender: false }, '<')
  tl.fromTo(
    qa('row-local'),
    { opacity: 0, y: 5 },
    { opacity: 1, y: 0, duration: 0.25, stagger: 0.05, immediateRender: false },
    '<',
  )
  move(`row-local-${keyId('nw.recentlyViewed')}`, { at: '+=0.2', ax: 0.5, ay: 0.7 })
  wait(0.8)

  step(1, '+=0.1')
  move('search')
  click('search')
  tl.to(q('search-ph'), { opacity: 0, duration: 0.1 }, '<')
  type('search-text', QUERY, { speed: 0.12 })
  collapse(HIDDEN, true)
  move(`copy-${keyId(COPIED[0])}`, { at: '+=0.1' })
  click(`copy-${keyId(COPIED[0])}`)
  tl.to(q(`copy-icon-${keyId(COPIED[0])}`), { opacity: 0, duration: 0.1 }, '<')
  tl.to(q(`copy-ok-${keyId(COPIED[0])}`), { opacity: 1, duration: 0.1 }, '<')
  tl.fromTo(
    q('clip'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, immediateRender: false },
    '<',
  )
  wait(1)

  step(2, '+=0.1')
  tl.to(q('clip'), { opacity: 0, duration: 0.2 })
  move('search', { at: '<', ax: 0.9 })
  click('search')
  tl.set(q('search-text'), { text: '' }, '<')
  tl.to(q('search-ph'), { opacity: 1, duration: 0.1 }, '<')
  collapse(HIDDEN, false)
  move('tab-session')
  click('tab-session')
  tab('session')
  move('continue')
  click('continue')
  tl.to(q('stage-ship'), { color: '#16a34a', duration: 0.15 }, '<')
  tl.to(q('stage-pay'), { color: '#111827', fontWeight: 700, duration: 0.15 }, '<')
  tl.to(q('form-ship'), { opacity: 0, duration: 0.2 }, '<')
  tl.to(q('form-pay'), { opacity: 1, duration: 0.2 }, '<0.1')
  move('refresh', { at: '+=0.2' })
  click('refresh')
  tl.to(q('refresh-icon'), { rotate: 360, duration: 0.5, ease: 'power2.inOut' }, '<')
  tl.set(q('value-checkout-step'), { text: STEP_AFTER }, '<0.3')
  tl.fromTo(
    q('row-session-checkout-step'),
    { backgroundColor: 'rgba(56,189,248,0.18)' },
    { backgroundColor: 'rgba(56,189,248,0)', duration: 1, immediateRender: false },
    '<',
  )
  cursorOut('+=0.3')
  final('+=0.1')
  wait(1.4)

  tl.set(
    [q('tabs'), q('clip'), q('list-session'), q('form-pay'), ...qa('copy-ok')],
    { opacity: 0 },
    0,
  )
  tl.set(
    [q('loading'), q('list-local'), q('search-ph'), q('form-ship'), ...qa('copy-icon')],
    { opacity: 1 },
    0,
  )
  tl.set(
    qa('row-local'),
    { height: 'auto', marginBottom: 4, borderWidth: 1, paddingTop: 5, paddingBottom: 5 },
    0,
  )
  tl.set(q('search-text'), { text: '' }, 0)
  tl.set(q('value-checkout-step'), { text: SESSION[1][1] }, 0)
  tl.set(q('refresh-icon'), { rotate: 0 }, 0)
  tl.set(q('tab-local'), { backgroundColor: 'var(--demo-tint-10)', color: 'var(--demo-ink)' }, 0)
  tl.set(q('tab-session'), { backgroundColor: 'rgba(255,255,255,0)', color: 'var(--demo-muted)' }, 0)
  tl.set(q('stage-ship'), { color: '#111827' }, 0)
  tl.set(q('stage-pay'), { color: '#9ca3af', fontWeight: 500 }, 0)
}

function Row({ which, entry }: { which: 'local' | 'session'; entry: Entry }) {
  const [key, value] = entry
  const id = keyId(key)
  return (
    <div
      data-d={`row-${which} row-${which}-${id}`}
      className="overflow-hidden rounded border border-line px-1.5"
      style={{ marginBottom: 4, paddingTop: 5, paddingBottom: 5 }}
    >
      <div className="flex items-center justify-between gap-1">
        <code className="min-w-0 truncate font-mono text-[8px] font-medium text-[var(--accent)]">
          {key}
        </code>
        <span
          data-d={`copy-${id}`}
          className="relative flex size-4 shrink-0 items-center justify-center rounded text-muted"
        >
          <CopyIcon data-d={`copy-icon copy-icon-${id}`} className="absolute size-2.5" />
          <CheckIcon
            data-d={`copy-ok copy-ok-${id}`}
            className="absolute size-2.5 text-emerald-400 opacity-0"
          />
        </span>
      </div>
      <code
        data-d={`value-${id}`}
        className="mt-0.5 block break-all font-mono text-[7.5px] leading-snug text-muted"
      >
        {preview(value)}
      </code>
    </div>
  )
}

function Panel() {
  return (
    <div className="flex h-full flex-col" style={{ width: PANEL }}>
      <DockHeader />
      <div className="flex min-h-0 flex-1 flex-col gap-1.5 p-2">
        <div className="flex items-center gap-1">
          <span
            data-d="search"
            className="relative flex h-6 flex-1 items-center gap-1 rounded-md border border-line-strong bg-canvas/80 px-1.5 text-[8.5px]"
          >
            <SearchIcon className="size-2.5 text-muted" />
            <span data-d="search-ph" className="absolute left-5 text-muted">
              Search…
            </span>
            <span data-d="search-text" className="font-mono text-ink" />
          </span>
          <span
            data-d="refresh"
            className="flex size-6 items-center justify-center rounded-md text-muted"
          >
            <RefreshCwIcon data-d="refresh-icon" className="size-3" />
          </span>
        </div>
        <p data-d="loading" className="absolute text-[8px] text-muted" style={{ top: 78 }}>
          Loading…
        </p>
        <div data-d="tabs" className="flex min-h-0 flex-1 flex-col opacity-0">
          <div className="grid grid-cols-2 gap-0.5 rounded-md bg-ink/[0.04] p-0.5">
            {(
              [
                ['local', 'localStorage', LOCAL.length],
                ['session', 'sessionStorage', SESSION.length],
              ] as const
            ).map(([which, label, count], index) => (
              <span
                key={which}
                data-d={`tab-${which}`}
                className={`flex items-center justify-center gap-1 rounded py-0.5 font-mono text-[8px] ${index === 0 ? 'bg-ink/10 text-ink' : 'text-muted'}`}
              >
                {label}
                <span className="rounded border border-line-strong px-1 font-sans text-[7px]">
                  {count}
                </span>
              </span>
            ))}
          </div>
          <div className="relative mt-1.5 min-h-0 flex-1 overflow-hidden">
            <div data-d="list-local" className="absolute inset-0">
              {LOCAL.map((entry) => (
                <Row key={entry[0]} which="local" entry={entry} />
              ))}
            </div>
            <div data-d="list-session" className="absolute inset-0 opacity-0">
              {SESSION.map((entry) => (
                <Row key={entry[0]} which="session" entry={entry} />
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function Page() {
  return (
    <div className="relative h-full bg-[#f9fafb] px-4 pt-3 text-[#111827]">
      <p className="text-[7px] font-semibold uppercase tracking-[0.2em] text-[#2563eb]">
        Northwind Outdoors
      </p>
      <h3 className="mt-0.5 text-[13px] font-bold">Checkout</h3>
      <div className="mt-1.5 flex gap-2 text-[8px]">
        <span className="text-[#16a34a]">Cart ✓</span>
        <span data-d="stage-ship" className="font-bold">
          Shipping
        </span>
        <span data-d="stage-pay" className="text-[#9ca3af]">
          Payment
        </span>
      </div>
      <div className="relative mt-2 h-[150px]">
        <div data-d="form-ship" className="absolute inset-0 space-y-1.5">
          {['Full name', 'Street address', 'City', 'Postcode'].map((label) => (
            <span key={label} className="block">
              <span className="block text-[7px] text-[#4b5563]">{label}</span>
              <span className="mt-0.5 block h-[16px] rounded border border-[#d1d5db] bg-white" />
            </span>
          ))}
          <span
            data-d="continue"
            className="mt-2 flex h-6 w-28 items-center justify-center rounded-md bg-[#2563eb] text-[8.5px] font-semibold text-white"
          >
            Continue to payment
          </span>
        </div>
        <div data-d="form-pay" className="absolute inset-0 space-y-1.5 opacity-0">
          <span className="block rounded-md border border-[#d1d5db] bg-white p-2 text-[8px]">
            <span className="font-semibold">Card</span>
            <span className="mt-1 block h-[16px] rounded border border-[#e5e7eb] bg-[#f9fafb]" />
          </span>
          <span className="block rounded-md border border-[#e5e7eb] bg-white p-2 text-[8px] text-[#6b7280]">
            PayPal
          </span>
        </div>
      </div>
      <div
        data-d="clip"
        className="absolute inset-x-3 bottom-3 rounded-lg border border-ink/10 bg-elevated p-2 opacity-0 shadow-2xl"
      >
        <p className="flex items-center gap-1 text-[8px] font-medium text-ink">
          <CheckIcon className="size-2.5 text-emerald-400" /> Copied value of {COPIED[0]}
        </p>
        <p className="mt-1 font-mono text-[8px] text-ink-soft">{COPIED[1]}</p>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`Storage inspector listing ${LOCAL.length} localStorage and ${SESSION.length} sessionStorage keys, filtering to ${MATCHES.length} feature flags, copying one, then refreshing to see the checkout step change`}
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome url="https://shop.northwind.dev/checkout" panelWidth={PANEL} panel={<Panel />}>
        <Page />
      </BrowserChrome>
    </DemoStage>
  )
}
